pm.test("TC01 - Status code is 200",function(){
    pm.response.to.have.status(200);
});

pm.test("Response time is less than 3000 ms",function(){
    pm.expect(pm.response.responseTime).to.be.below(3000);
});

pm.test("Response is an JSON array",function(){
    const books = pm.response.json();
    pm.expect(books).to.be.an("array");
});

pm.test("Each book has required fields",function(){
    const books = pm.response.json();
    pm.expect(books.length).to.be.above(0);
    books.forEach(function(book){
        pm.expect(book).to.have.property("id");
        pm.expect(book).to.have.property("title");
        pm.expect(book).to.have.property("pageCount");
    });
});

pm.test("TC02 - Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response contains the requested book ID", function () {
    const book = pm.response.json();
    pm.expect(book.id).to.eql(1);
});

pm.test("Book title is not empty", function () {
    const book = pm.response.json();
    pm.expect(book.title).to.be.a("string").and.not.empty;
});

pm.test("Book has a page count", function () {
    const book = pm.response.json();
    pm.expect(book).to.have.property("pageCount");
    pm.expect(book.pageCount).to.be.a("number");
});

pm.test("TC03 - Status code is successful", function () {
    pm.expect([200, 201]).to.include(pm.response.code);
});

pm.test("Response contains the book title", function () {
    const book = pm.response.json();
    pm.expect(book.title).to.eql("Postman API Testing Guide");
});

pm.test("Response contains the book ID", function () {
    const book = pm.response.json();
    pm.expect(book.id).to.eql(101);
});

pm.test("Response contains the correct page count", function () {
    const book = pm.response.json();
    pm.expect(book.pageCount).to.eql(250);
});

pm.test("TC04 - Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Updated title is returned", function () {
    const book = pm.response.json();
    pm.expect(book.title).to.eql("Updated Library Testing Book");
});

pm.test("Book ID is correct", function () {
    const book = pm.response.json();
    pm.expect(book.id).to.eql(1);
});

pm.test("Updated page count is returned", function () {
    const book = pm.response.json();
    pm.expect(book.pageCount).to.eql(300);
});

pm.test("TC05 - Status code indicates success", function () {
    pm.expect([200, 204]).to.include(pm.response.code);
});

